-- =====================================================================
--  July  —  the words, moved behind the paywall
--
--  WHAT THIS DOES
--  Creates `book_nights` if it is not there yet, and puts 28 nights of
--  There Is a Prophet in Israel into it. The table carries the same rule as
--  story_texts: Postgres hands a row to a subscriber, or to anyone for a
--  story marked free, and to nobody else.
--
--  HOW TO RUN IT
--    Supabase  ->  SQL Editor  ->  New query  ->  paste  ->  Ctrl+A  ->  Run
--
--  Safe to run more than once: it updates rather than duplicating.
--  Run the three book files in any order.
-- =====================================================================

create table if not exists public.book_nights (
  id         text primary key,   -- the catalog id, e.g. 'b6-w1-n1'
  book       int,
  night      text,               -- "Week 1 · Night 1"
  title      text,
  reference  text,
  beats      jsonb not null,     -- the whole night: pictures, words, moments
  is_free    boolean not null default false,
  updated_at timestamptz not null default now()
);

alter table public.book_nights enable row level security;

-- The same rule story_texts already uses. Editing the website's JavaScript
-- gets a reader precisely nothing, because the words never leave the database.
drop policy if exists "read book night" on public.book_nights;
create policy "read book night"
  on public.book_nights for select
  to authenticated
  using (is_free or public.lst_is_subscriber());

-- ---------------------------------------------------------------------
--  There Is a Prophet in Israel
-- ---------------------------------------------------------------------
insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n1', 7, 'Week 1 · Night 1', 'Two Kings, One Choice', '1 Kings 12', '[{"type": "cover", "img": "images/book/jul-01-0.jpg", "alt": "Cover illustration for “Two Kings, One Choice”"}, {"type": "story", "img": "images/book/jul-01-1.jpg", "alt": "Illustration: Long ago, wise King Solomon died.", "text": ["Long ago, wise King Solomon died. His son Rehoboam became the new king. The people came to him and said, “Please be kind and gentle to us.” Rehoboam said, “Give me three days to think.”", "First he asked the old, wise men what to do. They said, “Be kind, and the people will love you forever.” But then he asked his young friends. They told him, “Be tough and bossy!”"]}, {"type": "story", "img": "images/book/jul-01-2.jpg", "alt": "Illustration: Rehoboam listened to his friends instead of the wise men.", "text": ["Rehoboam listened to his friends instead of the wise men. He spoke harsh, unkind words to the people. This made everyone sad and upset. The kingdom split into two pieces.", "Heavenly Father gives us wise people to guide us — parents, prophets, and teachers. When we listen to them, our hearts stay happy and safe. When we ignore good counsel, things can fall apart. Wise listening keeps families together."]}, {"type": "moment", "img": "images/book/jul-01-3.jpg", "alt": "Illustration: Cup your hands behind your ears like big bunny ears.", "text": ["Cup your hands behind your ears like big bunny ears. Now listen very carefully — can you hear quiet sounds in the room? That is good listening! Rehoboam forgot to listen to the wise men, and it made everything hard. Let’s practice listening to the people who love us."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU can be a good listener! When mom or dad asks you to do something, listen the first time. When your teacher gives you a rule, follow it. Wise people want to keep you safe and happy. Who is someone wise you can listen to this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-01-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who did Rehoboam listen to? What happened to the kingdom when he didn’t listen to the wise men?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-01-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n2', 7, 'Week 1 · Night 2', 'The Ravens Feed Elijah', '1 Kings 17', '[{"type": "cover", "img": "images/book/jul-02-0.jpg", "alt": "Cover illustration for “The Ravens Feed Elijah”"}, {"type": "story", "img": "images/book/jul-02-1.jpg", "alt": "Illustration: Elijah was a prophet who loved Heavenly Father.", "text": ["Elijah was a prophet who loved Heavenly Father. He told the wicked king there would be no rain for a long time. Then Heavenly Father said, “Go hide by the little brook. I will take care of you.”", "Elijah went and stayed by the brook. He drank the cool, clear water. But where would he get food? There were no stores out there."]}, {"type": "story", "img": "images/book/jul-02-2.jpg", "alt": "Illustration: Then something amazing happened!", "text": ["Then something amazing happened! Big black birds called ravens flew to Elijah. They carried bread and meat in their beaks. They brought him food every morning and every night.", "Heavenly Father took care of Elijah in a surprising way. He uses all sorts of helpers — even birds! When we trust Him, He always finds a way to take care of us. Heavenly Father never forgets His children."]}, {"type": "moment", "img": "images/book/jul-02-3.jpg", "alt": "Illustration: Flap your arms like a bird carrying food.", "text": ["Flap your arms like a bird carrying food. Now “fly” your hands over and drop pretend bread into someone’s lap. That’s what the ravens did for Elijah! Heavenly Father sent them so Elijah would not be hungry. Think about all the ways He takes care of YOU."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father takes care of you every single day! He gives you food, a home, and people who love you. Sometimes His help comes in surprising ways. When you wonder if He sees you, remember the ravens. What is one way Heavenly Father took care of you today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-02-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who brought Elijah food? Who sent the ravens to help him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-02-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n3', 7, 'Week 1 · Night 3', 'The Jar That Never Ran Out', '1 Kings 17', '[{"type": "cover", "img": "images/book/jul-03-0.jpg", "alt": "Cover illustration for “The Jar That Never Ran Out”"}, {"type": "story", "img": "images/book/jul-03-1.jpg", "alt": "Illustration: Heavenly Father sent Elijah to a poor widow in another town.", "text": ["Heavenly Father sent Elijah to a poor widow in another town. She had a little boy and almost no food left. She had just a tiny bit of flour and a tiny bit of oil. She thought it was their very last meal.", "Elijah said, “Please make me a little bread first. Don’t be afraid.” The woman was kind. She shared her last food with the prophet, even though she was scared."]}, {"type": "story", "img": "images/book/jul-03-2.jpg", "alt": "Illustration: Then a miracle happened!", "text": ["Then a miracle happened! Her jar of flour never got empty. Her oil never ran out. Every day there was enough food for the widow, her son, and Elijah.", "Because the woman trusted God and shared, He blessed her with plenty. When we give even when it’s hard, Heavenly Father takes care of us. Sharing opens the door for blessings. God can make a little become a lot."]}, {"type": "moment", "img": "images/book/jul-03-3.jpg", "alt": "Illustration: Pretend to pour from a jar — tip your hand and say “glug, glug, glug.” Now pour again…", "text": ["Pretend to pour from a jar — tip your hand and say “glug, glug, glug.” Now pour again… and again… it never runs out! That’s the miracle Heavenly Father gave the widow. He turned her little bit into more than enough."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you share, Heavenly Father is so pleased! Sharing your snack, your toys, or your turn can feel hard. But God blesses people who give with a happy heart. What is something you can share this week, even if it feels hard?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-03-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the widow share with Elijah? What happened to her flour and oil?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-03-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n4', 7, 'Week 1 · Night 4', 'Elijah Prays for the Little Boy', '1 Kings 17', '[{"type": "cover", "img": "images/book/jul-04-0.jpg", "alt": "Cover illustration for “Elijah Prays for the Little Boy”"}, {"type": "story", "img": "images/book/jul-04-1.jpg", "alt": "Illustration: The widow’s little boy got very, very sick.", "text": ["The widow’s little boy got very, very sick. He got so sick that he stopped breathing. His mother was heartbroken and cried. She did not know what to do.", "Elijah said, “Give me your son.” He carried the boy upstairs and laid him down. Then Elijah prayed to Heavenly Father with all his heart. “Please, Lord, let this child live again.”"]}, {"type": "story", "img": "images/book/jul-04-2.jpg", "alt": "Illustration: Heavenly Father heard Elijah’s prayer.", "text": ["Heavenly Father heard Elijah’s prayer. The little boy started breathing again! Elijah carried him back down to his mother. “See,” he said, “your son is alive!”", "The mother knew for sure that Elijah was God’s prophet. Prayer is powerful because Heavenly Father is listening. He hears every prayer we say. Nothing is too hard for Him."]}, {"type": "moment", "img": "images/book/jul-04-3.jpg", "alt": "Illustration: Fold your arms and bow your head like Elijah praying.", "text": ["Fold your arms and bow your head like Elijah praying. Whisper, “Please help, Heavenly Father.” Feel how quiet and peaceful that is. Heavenly Father heard Elijah, and He hears you too."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When something feels too big or too scary, YOU can pray! Heavenly Father loves to hear from you. He listened to Elijah, and He listens to little children just the same. What is something you can pray about tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-04-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Elijah do when the boy was sick? Did Heavenly Father hear his prayer?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-04-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n5', 7, 'Week 1 · Night 5', 'Fire from Heaven', '1 Kings 18', '[{"type": "cover", "img": "images/book/jul-05-0.jpg", "alt": "Cover illustration for “Fire from Heaven”"}, {"type": "story", "img": "images/book/jul-05-1.jpg", "alt": "Illustration: Many people had forgotten Heavenly Father.", "text": ["Many people had forgotten Heavenly Father. They worshiped a pretend god named Baal. Elijah said, “Let’s find out who the real God is!” He gathered everyone on top of a mountain.", "The prophets of Baal called and called to their pretend god all day. But nothing happened — no answer at all. Baal was not real, so he could not hear them."]}, {"type": "story", "img": "images/book/jul-05-2.jpg", "alt": "Illustration: Then Elijah built an altar and prayed to the true God.", "text": ["Then Elijah built an altar and prayed to the true God. He even poured water all over it! Suddenly, FIRE came down from heaven and burned it all up — the water, the wood, even the stones!", "Everyone fell down and said, “The Lord, He is the real God!” There is only one true God — our Heavenly Father. He is real, He is powerful, and He hears us. We follow Him because He is true."]}, {"type": "moment", "img": "images/book/jul-05-3.jpg", "alt": "Illustration: Wiggle your fingers up high like flickering flames, then bring them whooshing down — that’s the fire from heav…", "text": ["Wiggle your fingers up high like flickering flames, then bring them whooshing down — that’s the fire from heaven! Heavenly Father showed everyone He was real. Make your hands strong and say, “The Lord, He is God!”"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["There is only ONE true God — your Heavenly Father! He is more real and more powerful than anything pretend. We don’t follow toys, or money, or anything else more than Him. We choose Him first. How can you show Heavenly Father that you choose Him?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-05-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What came down from heaven for Elijah? Who is the one true God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-05-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n6', 7, 'Week 1 · Night 6', 'The Still, Small Voice', '1 Kings 19', '[{"type": "cover", "img": "images/book/jul-06-0.jpg", "alt": "Cover illustration for “The Still, Small Voice”"}, {"type": "story", "img": "images/book/jul-06-1.jpg", "alt": "Illustration: Elijah was tired and scared and ran far away.", "text": ["Elijah was tired and scared and ran far away. He sat down all alone and felt very sad. Heavenly Father sent an angel to bring him food and rest. Then God told Elijah to wait on the mountain.", "First came a big, loud WIND that broke the rocks. But God was not in the wind. Then came a shaking EARTHQUAKE. But God was not in the earthquake."]}, {"type": "story", "img": "images/book/jul-06-2.jpg", "alt": "Illustration: Then came a hot, crackling FIRE.", "text": ["Then came a hot, crackling FIRE. But God was not in the fire either. After all the loud noise came a tiny, gentle whisper. And THAT is where Elijah felt God.", "Heavenly Father often speaks in a quiet, peaceful way. It’s a soft feeling inside, called the Holy Ghost. To hear Him, we have to be calm and still. His gentle voice guides us to what is right."]}, {"type": "moment", "img": "images/book/jul-06-3.jpg", "alt": "Illustration: Make a big loud “WHOOOSH” wind sound, then stomp like an earthquake, then “crackle” like fire.", "text": ["Make a big loud “WHOOOSH” wind sound, then stomp like an earthquake, then “crackle” like fire. Now… get very, very still and quiet. Shhh. That stillness is where Elijah felt God. Can you feel how peaceful quiet can be?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father usually speaks in a quiet, gentle way — through the Holy Ghost. It’s a warm, peaceful feeling in your heart. To hear Him, you have to be calm and listen. When have you felt that quiet, good feeling inside?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-06-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Was God in the loud wind, earthquake, or fire? Where did Elijah finally feel God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-06-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n7', 7, 'Week 1 · Night 7', 'Micaiah Tells the Truth', '1 Kings 22', '[{"type": "cover", "img": "images/book/jul-07-0.jpg", "alt": "Cover illustration for “Micaiah Tells the Truth”"}, {"type": "story", "img": "images/book/jul-07-1.jpg", "alt": "Illustration: King Ahab wanted to go to a big battle.", "text": ["King Ahab wanted to go to a big battle. He gathered lots of prophets who only said what he wanted to hear. “You’ll win! You’ll win!” they cheered. But that wasn’t really true.", "There was one true prophet named Micaiah. The king didn’t like him because Micaiah always told the truth. The messenger said, “Just say something nice like everyone else.” But Micaiah said, “I will only say what God tells me.”"]}, {"type": "story", "img": "images/book/jul-07-2.jpg", "alt": "Illustration: Micaiah bravely told the truth: “If you go to battle, it will not go well.” The king got angry and put Micaiah…", "text": ["Micaiah bravely told the truth: “If you go to battle, it will not go well.” The king got angry and put Micaiah away. But Micaiah was right — he had told the truth.", "Telling the truth can be hard, especially when others want you to fib. But Heavenly Father wants us to be honest, even when it’s scary. Brave, truthful people please the Lord. Truth is always the right choice."]}, {"type": "moment", "img": "images/book/jul-07-3.jpg", "alt": "Illustration: Stand up tall and strong like brave Micaiah.", "text": ["Stand up tall and strong like brave Micaiah. Put your hand on your heart and say, “I will tell the truth!” It takes courage to be honest when others want you to fib. Feel how good and clean it feels to tell the truth."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Always tell the truth, even when it’s hard! Sometimes people want you to fib, or you might be scared of getting in trouble. But Heavenly Father is so happy when you are honest. When is a time it might be hard to tell the truth — and you can choose to be honest anyway?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-07-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Did Micaiah say what the king wanted, or did he tell the truth? Was telling the truth easy or hard?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-07-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n1', 7, 'Week 2 · Night 1', 'Elijah Goes Up to Heaven', '2 Kings 2', '[{"type": "cover", "img": "images/book/jul-08-0.jpg", "alt": "Cover illustration for “Elijah Goes Up to Heaven”"}, {"type": "story", "img": "images/book/jul-08-1.jpg", "alt": "Illustration: Elijah the prophet was very old.", "text": ["Elijah the prophet was very old. His helper Elisha loved him and stayed close by his side. Elisha would not leave Elijah, no matter what. They walked together as good friends.", "They came to a river. Elijah rolled up his coat and hit the water. The river split apart so they could walk across on dry ground! Heavenly Father gave Elijah great power."]}, {"type": "story", "img": "images/book/jul-08-2.jpg", "alt": "Illustration: Suddenly a chariot of fire and horses of fire came down!", "text": ["Suddenly a chariot of fire and horses of fire came down! Elijah went up, up, up to heaven in a whirlwind. Elisha watched in wonder. Then Elijah’s coat floated down to him.", "Now Elisha became the new prophet. He picked up the coat and trusted God just like Elijah did. Heavenly Father always has a living prophet to lead His people. When one prophet finishes, another is ready to help us."]}, {"type": "moment", "img": "images/book/jul-08-3.jpg", "alt": "Illustration: Whirl your arms around like a spinning whirlwind going up to the sky — wheee!", "text": ["Whirl your arms around like a spinning whirlwind going up to the sky — wheee! That’s how Elijah went to heaven. Then pretend to pick up his special coat, like Elisha did. Now YOU can be a helper who follows God’s prophet."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father always gives us a living prophet to lead us! Today we have a prophet too. He helps us know what God wants. When we follow the prophet, we follow Heavenly Father. Do you know the name of our prophet today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-08-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How did Elijah go up to heaven? Who became the new prophet after him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-08-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n2', 7, 'Week 2 · Night 2', 'The Widow’s Oil', '2 Kings 4', '[{"type": "cover", "img": "images/book/jul-09-0.jpg", "alt": "Cover illustration for “The Widow’s Oil”"}, {"type": "story", "img": "images/book/jul-09-1.jpg", "alt": "Illustration: A kind woman was very sad.", "text": ["A kind woman was very sad. Her husband had died, and she owed money she could not pay. All she had left was one little pot of oil. She came to the prophet Elisha for help.", "Elisha said, “Go borrow lots of empty jars from your neighbors. Get as many as you can!” So she and her sons gathered jars and jars and jars. Then they shut the door."]}, {"type": "story", "img": "images/book/jul-09-2.jpg", "alt": "Illustration: She started pouring her little bit of oil.", "text": ["She started pouring her little bit of oil. But it kept pouring and pouring! It filled every single jar, right to the top. The oil only stopped when there were no more jars left.", "Elisha said, “Now sell the oil and pay what you owe.” Heavenly Father gave her more than enough. When we trust God and obey His prophet, He provides. He cares about our family’s needs."]}, {"type": "moment", "img": "images/book/jul-09-3.jpg", "alt": "Illustration: Pretend you’re holding a jar and pouring oil — tip your hand and watch it fill up…", "text": ["Pretend you’re holding a jar and pouring oil — tip your hand and watch it fill up… and another… and another! It just keeps coming! That’s the miracle God gave the widow. He took her little bit and made it more than enough.", "Sweet Boys & Girls"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you obey, Heavenly Father can do amazing things! The widow listened to the prophet and got a miracle. God knows what your family needs. He can make your “little bit” into plenty. What is something you can obey cheerfully this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-09-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the widow have at the start? What happened when she poured her oil?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-09-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n3', 7, 'Week 2 · Night 3', 'A Special Room for the Prophet', '2 Kings 4', '[{"type": "cover", "img": "images/book/jul-10-0.jpg", "alt": "Cover illustration for “A Special Room for the Prophet”"}, {"type": "story", "img": "images/book/jul-10-1.jpg", "alt": "Illustration: There was a kind woman who loved Heavenly Father.", "text": ["There was a kind woman who loved Heavenly Father. Whenever Elisha walked by, she gave him food. She told her husband, “Let’s make a little room for the prophet.” So they built him a cozy room with a bed, a table, a chair, and a lamp.", "Elisha was so thankful for her kindness. He wanted to do something nice for her too. He asked, “What can I do for you?” The woman had always wished for a baby."]}, {"type": "story", "img": "images/book/jul-10-2.jpg", "alt": "Illustration: Elisha said, “Next year you will hold a baby boy in your arms.” The woman could hardly believe it!", "text": ["Elisha said, “Next year you will hold a baby boy in your arms.” The woman could hardly believe it! And it came true — she had a sweet baby son. Heavenly Father blessed her kindness.", "When we are kind and make room for others, Heavenly Father notices. He blesses people who serve quietly and lovingly. Kindness is never wasted. God remembers every good thing we do."]}, {"type": "moment", "img": "images/book/jul-10-3.jpg", "alt": "Illustration: Pretend to fluff a pillow and pat a cozy bed — you’re making a nice room for someone special!", "text": ["Pretend to fluff a pillow and pat a cozy bed — you’re making a nice room for someone special! That’s what the kind woman did for the prophet. Now give a warm, welcoming wave like you’re saying, “Come in, you’re welcome here!”"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Being kind and welcoming makes Heavenly Father happy! You can make room for others — share your space, your snack, or a smile. The kind woman served the prophet, and God blessed her. Who can you be kind and welcoming to this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-10-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the kind woman build for the prophet? How did Heavenly Father bless her?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-10-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n4', 7, 'Week 2 · Night 4', 'Naaman Washes Seven Times', '2 Kings 5', '[{"type": "cover", "img": "images/book/jul-11-0.jpg", "alt": "Cover illustration for “Naaman Washes Seven Times”"}, {"type": "story", "img": "images/book/jul-11-1.jpg", "alt": "Illustration: Naaman was a strong, important soldier.", "text": ["Naaman was a strong, important soldier. But he was very sick with sores all over his skin. A little servant girl said, “There’s a prophet who can help you!” So Naaman traveled to find Elisha.", "Elisha sent a simple message: “Go wash in the river seven times.” Naaman was upset! “That’s too easy. Why didn’t he do something fancy?” He almost went home still sick."]}, {"type": "story", "img": "images/book/jul-11-2.jpg", "alt": "Illustration: But his servants said kindly, “Just try it!” So Naaman dipped in the river — one, two, three, four, five, six…", "text": ["But his servants said kindly, “Just try it!” So Naaman dipped in the river — one, two, three, four, five, six, seven times. When he came up, his skin was all better! He was completely healed.", "Sometimes Heavenly Father asks us to do simple things. They might seem too easy, but obeying brings big blessings. Naaman learned to be humble and obey. Doing the small things God asks really matters."]}, {"type": "moment", "img": "images/book/jul-11-3.jpg", "alt": "Illustration: Let’s count and dip together!", "text": ["Let’s count and dip together! Pretend to dip down in the water seven times — “one, two, three, four, five, six, seven!” Now pop up clean and healthy like Naaman! Doing the simple thing God asked made all the difference."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Do the simple things Heavenly Father asks, even if they seem small! Saying prayers, being kind, listening, and obeying might feel plain. But those little things bring big blessings. What simple, good thing can you do today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-11-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Elisha tell Naaman to do? Was Naaman healed when he finally obeyed?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-11-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n5', 7, 'Week 2 · Night 5', 'The Floating Axe Head', '2 Kings 6', '[{"type": "cover", "img": "images/book/jul-12-0.jpg", "alt": "Cover illustration for “The Floating Axe Head”"}, {"type": "story", "img": "images/book/jul-12-1.jpg", "alt": "Illustration: Elisha and his helpers were chopping wood by the river.", "text": ["Elisha and his helpers were chopping wood by the river. They were building a new place to live and work. One man was swinging hard with a borrowed axe. Suddenly — splash! — the metal axe head flew off into the deep water.", "The man felt terrible. “Oh no! That axe wasn’t even mine — I borrowed it!” He was worried because he could not pay for it. He didn’t know what to do."]}, {"type": "story", "img": "images/book/jul-12-2.jpg", "alt": "Illustration: Elisha asked, “Where did it fall?” The man showed him the spot.", "text": ["Elisha asked, “Where did it fall?” The man showed him the spot. Elisha cut a stick and threw it in the water. Then the heavy iron axe head floated right up to the top!", "Heavenly Father cares about big things AND little things. He helped with a lost axe head because His prophet asked. No worry is too small for God. He loves us and helps with everything."]}, {"type": "moment", "img": "images/book/jul-12-3.jpg", "alt": "Illustration: Pretend to swing an axe — chop, chop, chop — then “whoops!” let it splash into the water.", "text": ["Pretend to swing an axe — chop, chop, chop — then “whoops!” let it splash into the water. Now use your finger to make the axe head float up, up to the top! Heavenly Father cared about that little lost axe. He cares about your little worries too."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["No problem is too small for Heavenly Father! Maybe you lost a toy, or you’re worried about something little. You can still talk to Him about it. He cared about a lost axe head, and He cares about YOU. What little thing can you tell Heavenly Father about today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-12-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the man lose in the water? What did Elisha do to help?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-12-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n6', 7, 'Week 2 · Night 6', 'Horses of Fire All Around', '2 Kings 6', '[{"type": "cover", "img": "images/book/jul-13-0.jpg", "alt": "Cover illustration for “Horses of Fire All Around”"}, {"type": "story", "img": "images/book/jul-13-1.jpg", "alt": "Illustration: An enemy army wanted to catch Elisha.", "text": ["An enemy army wanted to catch Elisha. One morning, Elisha’s young helper woke up and saw soldiers all around the city! “Oh no!” he cried. “What are we going to do?”", "But Elisha was calm. “Don’t be afraid,” he said. “There are more helpers with us than there are enemies.” The young man looked around and felt scared and confused. He couldn’t see any helpers."]}, {"type": "story", "img": "images/book/jul-13-2.jpg", "alt": "Illustration: So Elisha prayed, “Lord, open his eyes so he can see.” Suddenly the young man saw the hills full of horses and…", "text": ["So Elisha prayed, “Lord, open his eyes so he can see.” Suddenly the young man saw the hills full of horses and chariots of FIRE! God’s mighty helpers were everywhere, protecting them.", "Heavenly Father sends help we cannot always see. Angels and His power are all around us. When we feel scared, we don’t have to be — God is bigger than anything. We are never really alone."]}, {"type": "moment", "img": "images/book/jul-13-3.jpg", "alt": "Illustration: Cover your eyes with your hands like the scared helper.", "text": ["Cover your eyes with your hands like the scared helper. Now open them wide and look all around — “Wow! Horses of fire everywhere!” Heavenly Father had helpers all around them the whole time. He has helpers around you too, even when you can’t see them."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you feel scared, remember: Heavenly Father’s helpers are all around you! You can’t always see them, but they are there. God is stronger than anything that scares you. You are never alone. What helps you feel brave when you’re afraid?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-13-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Elisha’s helper see after Elisha prayed? Who has more helpers — God’s side or the enemy’s?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-13-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n7', 7, 'Week 2 · Night 7', 'Good News to Share', '2 Kings 7', '[{"type": "cover", "img": "images/book/jul-14-0.jpg", "alt": "Cover illustration for “Good News to Share”"}, {"type": "story", "img": "images/book/jul-14-1.jpg", "alt": "Illustration: There was no food in the city, and everyone was hungry.", "text": ["There was no food in the city, and everyone was hungry. Four men sat outside the gate, hungry too. “Let’s go to the enemy camp,” they said. “Maybe they’ll give us food.” But when they got there — the camp was empty!", "Heavenly Father had made the enemies run away in fear. They left behind food, gold, clothes, everything! The four men ate and ate. They were so happy and full."]}, {"type": "story", "img": "images/book/jul-14-2.jpg", "alt": "Illustration: Then they stopped and said, “This is good news!", "text": ["Then they stopped and said, “This is good news! We can’t keep it to ourselves. Everyone in the city is hungry — we have to tell them!” So they hurried back to share the wonderful news.", "Soon the whole city had food, just like the prophet said! When we have good news, we share it. The gospel is the best news of all. Heavenly Father wants us to share His love with everyone."]}, {"type": "moment", "img": "images/book/jul-14-3.jpg", "alt": "Illustration: Cup your hands around your mouth and call out, “I have good news!” Now run in place like the four men hurrying…", "text": ["Cup your hands around your mouth and call out, “I have good news!” Now run in place like the four men hurrying to tell everyone. Sharing good news makes everyone happy! The best news of all is that Heavenly Father loves us."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you know something wonderful, share it! The men found food and shared it with everyone. You know the best news of all — that Heavenly Father and Jesus love you! Who can you share Heavenly Father’s love with this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-14-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the four men find in the camp? Why did they decide to share the good news?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-14-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n1', 7, 'Week 3 · Night 1', 'Good King Hezekiah Trusts God', '2 Kings 18', '[{"type": "cover", "img": "images/book/jul-15-0.jpg", "alt": "Cover illustration for “Good King Hezekiah Trusts God”"}, {"type": "story", "img": "images/book/jul-15-1.jpg", "alt": "Illustration: Hezekiah became the king of Judah.", "text": ["Hezekiah became the king of Judah. He loved Heavenly Father with all his heart. The people had been worshiping pretend gods and idols. Hezekiah said, “We will follow the true God!”", "He took away all the idols and false things. He helped the people remember Heavenly Father. Hezekiah trusted God more than any king before him. He held tight to the Lord and obeyed Him."]}, {"type": "story", "img": "images/book/jul-15-2.jpg", "alt": "Illustration: Because Hezekiah trusted God, Heavenly Father was with him.", "text": ["Because Hezekiah trusted God, Heavenly Father was with him. The Lord helped him and blessed the people. When troubles came, Hezekiah knew where to turn. He always looked to God first.", "Trusting Heavenly Father means believing He will help us. It means choosing Him over everything else. When we trust God, He stays close to us. Trusting God is the best choice a heart can make."]}, {"type": "moment", "img": "images/book/jul-15-3.jpg", "alt": "Illustration: Reach out and grab a grown-up’s hand and hold on tight — don’t let go!", "text": ["Reach out and grab a grown-up’s hand and hold on tight — don’t let go! That’s how Hezekiah held onto Heavenly Father, trusting Him completely. Holding God’s hand keeps us safe and brave. Who can you trust and hold onto?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Trusting Heavenly Father means believing He loves you and will help you. King Hezekiah trusted God and got rid of anything that pulled him away. You can trust God too — He is always there for you. How can you show Heavenly Father you trust Him?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-15-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hezekiah get rid of so the people could follow God? Did Hezekiah trust the Lord?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-15-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n2', 7, 'Week 3 · Night 2', 'Hezekiah Shows God the Letter', '2 Kings 19', '[{"type": "cover", "img": "images/book/jul-16-0.jpg", "alt": "Cover illustration for “Hezekiah Shows God the Letter”"}, {"type": "story", "img": "images/book/jul-16-1.jpg", "alt": "Illustration: A scary enemy king sent King Hezekiah a mean letter.", "text": ["A scary enemy king sent King Hezekiah a mean letter. The letter said, “We’re going to win! Your God can’t save you!” Hezekiah felt worried and afraid. What should he do?", "Hezekiah didn’t fight or panic. Instead, he took the letter straight to the temple. He spread the letter open before Heavenly Father. “Please, Lord, see this and help us,” he prayed."]}, {"type": "story", "img": "images/book/jul-16-2.jpg", "alt": "Illustration: Heavenly Father heard Hezekiah’s prayer.", "text": ["Heavenly Father heard Hezekiah’s prayer. He sent the prophet Isaiah with a message: “Don’t be afraid. I will protect this city.” And God did! He saved His people that very night.", "When we have a big worry, we can bring it to Heavenly Father. We can “spread it out” before Him in prayer. He listens, and He helps. Taking our troubles to God is always the right thing to do."]}, {"type": "moment", "img": "images/book/jul-16-3.jpg", "alt": "Illustration: Pretend you have a worry in your hands.", "text": ["Pretend you have a worry in your hands. Now “spread it out” and lay it down in front of you, like Hezekiah laid the letter before God. Take a deep breath out — whoosh — and let the worry go. Heavenly Father can carry our worries for us."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you’re worried or scared, take it to Heavenly Father! Hezekiah didn’t keep his worry inside — he spread it out before God in prayer. You can tell Heavenly Father exactly what’s bothering you. What worry can you give to Heavenly Father tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-16-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hezekiah do with the scary letter? Did Heavenly Father help him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-16-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n3', 7, 'Week 3 · Night 3', 'God Gives Hezekiah More Days', '2 Kings 20', '[{"type": "cover", "img": "images/book/jul-17-0.jpg", "alt": "Cover illustration for “God Gives Hezekiah More Days”"}, {"type": "story", "img": "images/book/jul-17-1.jpg", "alt": "Illustration: One day King Hezekiah got very, very sick.", "text": ["One day King Hezekiah got very, very sick. The prophet said he might not get better. Hezekiah was sad. He turned his face to the wall and prayed and cried to Heavenly Father.", "“Please, Lord, remember how I have tried to follow You.” Heavenly Father heard his prayer right away. He told the prophet, “Go back and tell Hezekiah I have heard him. I will make him well.”"]}, {"type": "story", "img": "images/book/jul-17-2.jpg", "alt": "Illustration: God promised Hezekiah fifteen more years of life!", "text": ["God promised Hezekiah fifteen more years of life! As a special sign, He even made a shadow move backward. Hezekiah got better, just like Heavenly Father said.", "Heavenly Father hears our prayers, even when we are very sad. He loves us and answers in the way that is best. Hezekiah trusted God, and God blessed him. Prayer brings us close to our Father in Heaven."]}, {"type": "moment", "img": "images/book/jul-17-3.jpg", "alt": "Illustration: Put your hand over your heart and say a quiet “thank you” to Heavenly Father, like Hezekiah did when he got be…", "text": ["Put your hand over your heart and say a quiet “thank you” to Heavenly Father, like Hezekiah did when he got better. Feel your heart beating — that’s a gift from God! Heavenly Father gives us each day. Let’s be thankful for the days we have."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father hears your prayers, even when you’re sad! Hezekiah prayed when he was sick, and God answered him. You can pray when you feel sick, sad, or scared. What is something you can thank Heavenly Father for today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-17-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hezekiah do when he was very sick? How did Heavenly Father answer him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-17-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n4', 7, 'Week 3 · Night 4', 'The Boy Who Became King', '2 Kings 22', '[{"type": "cover", "img": "images/book/jul-18-0.jpg", "alt": "Cover illustration for “The Boy Who Became King”"}, {"type": "story", "img": "images/book/jul-18-1.jpg", "alt": "Illustration: There was a little boy named Josiah.", "text": ["There was a little boy named Josiah. When he was only eight years old, he became the king! That’s younger than some of your friends. But Josiah had a good and tender heart.", "Even though he was young, Josiah wanted to do what was right. The kings before him had made many bad choices. But Josiah chose to follow Heavenly Father. He did not turn to the left or the right."]}, {"type": "story", "img": "images/book/jul-18-2.jpg", "alt": "Illustration: Josiah didn’t say, “I’m too little to be good.” He just tried his best to please the Lord every day.", "text": ["Josiah didn’t say, “I’m too little to be good.” He just tried his best to please the Lord every day. People could see his good heart. He became a wonderful king.", "You are never too young to be good! Heavenly Father is pleased when little children choose the right. Josiah was small, but his good choices were big. You can be like Josiah today."]}, {"type": "moment", "img": "images/book/jul-18-3.jpg", "alt": "Illustration: Stand up tall and proud, even though you’re little — like young King Josiah!", "text": ["Stand up tall and proud, even though you’re little — like young King Josiah! Put on a pretend crown and say, “I can choose the right!” You don’t have to be big to be good. Heavenly Father loves your good choices, no matter how little you are."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You are NEVER too young to choose the right! Josiah was just eight years old, but he had a good heart and followed God. You can be kind, honest, and obedient right now, today. What good choice can you make today, even though you’re little?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-18-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How old was Josiah when he became king? Did he choose to follow Heavenly Father?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-18-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n5', 7, 'Week 3 · Night 5', 'The Lost Book Is Found', '2 Kings 22', '[{"type": "cover", "img": "images/book/jul-19-0.jpg", "alt": "Cover illustration for “The Lost Book Is Found”"}, {"type": "story", "img": "images/book/jul-19-1.jpg", "alt": "Illustration: King Josiah wanted to fix up the temple, God’s house.", "text": ["King Josiah wanted to fix up the temple, God’s house. The workers cleaned and repaired it carefully. While they were working, they found something amazing. It was a long-lost book — the holy scriptures!", "The people had forgotten about God’s words for a long, long time. The priest brought the book to King Josiah. When Josiah heard the scriptures read out loud, he listened with all his heart."]}, {"type": "story", "img": "images/book/jul-19-2.jpg", "alt": "Illustration: Josiah was so moved that he tore his clothes — that’s how people showed strong feelings back then.", "text": ["Josiah was so moved that he tore his clothes — that’s how people showed strong feelings back then. He realized the people had not been following God’s words. “We need to obey what the scriptures say!” he said.", "The scriptures are God’s words to us, and they are precious. They teach us how to be happy and good. Josiah treasured them. We can read and listen to the scriptures too."]}, {"type": "moment", "img": "images/book/jul-19-3.jpg", "alt": "Illustration: Pretend to open a big, special book and hug it close to your heart.", "text": ["Pretend to open a big, special book and hug it close to your heart. The scriptures are a treasure! Run your finger across a pretend page like you’re reading God’s words. Heavenly Father speaks to us through the scriptures. Aren’t we lucky to have them?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["The scriptures are a special treasure from Heavenly Father! They are full of His words, just for us. King Josiah was so happy to find them and obey them. You can listen to scripture stories every day, like right now! How does it feel to hear stories from God’s word?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-19-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What special book did the workers find in the temple? How did King Josiah feel when he heard God’s words?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-19-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n6', 7, 'Week 3 · Night 6', 'Huldah Speaks for God', '2 Kings 22', '[{"type": "cover", "img": "images/book/jul-20-0.jpg", "alt": "Cover illustration for “Huldah Speaks for God”"}, {"type": "story", "img": "images/book/jul-20-1.jpg", "alt": "Illustration: King Josiah had a big question.", "text": ["King Josiah had a big question. He wanted to know what Heavenly Father thought about His people. So he sent his helpers to ask a wise woman named Huldah. Huldah was a prophetess — God spoke through her.", "The helpers came to Huldah and asked for God’s message. Huldah listened to the Lord. Then she told them exactly what Heavenly Father wanted to say. She spoke God’s truth bravely and clearly."]}, {"type": "story", "img": "images/book/jul-20-2.jpg", "alt": "Illustration: Huldah said the Lord saw Josiah’s tender, humble heart.", "text": ["Huldah said the Lord saw Josiah’s tender, humble heart. Because Josiah had listened and tried so hard, God would bless him. The king was grateful for her message from the Lord.", "Heavenly Father speaks through people He chooses, like Huldah and the prophets. When we listen to them, we hear God’s words. God can use anyone with a willing heart. We can listen and obey His messengers."]}, {"type": "moment", "img": "images/book/jul-20-3.jpg", "alt": "Illustration: Cup your hand to your ear and listen carefully, like Josiah’s helpers listening to Huldah.", "text": ["Cup your hand to your ear and listen carefully, like Josiah’s helpers listening to Huldah. Now nod your head “yes” to show you’ll obey. Heavenly Father gives us messengers to share His words. When we listen, we stay close to God."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father speaks through special people He chooses! Huldah listened to God and shared His message bravely. When we listen to prophets and good leaders, we hear what God wants. Who is someone who teaches you about Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-20-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who did the king’s helpers ask about God’s message? What did Huldah do?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-20-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n7', 7, 'Week 3 · Night 7', 'King Josiah Makes a Promise', '2 Kings 23', '[{"type": "cover", "img": "images/book/jul-21-0.jpg", "alt": "Cover illustration for “King Josiah Makes a Promise”"}, {"type": "story", "img": "images/book/jul-21-1.jpg", "alt": "Illustration: After hearing God’s words, King Josiah gathered all the people together.", "text": ["After hearing God’s words, King Josiah gathered all the people together. He read the holy scriptures out loud so everyone could hear. Then he made a special promise to Heavenly Father. “We will love God and keep His commandments!”", "All the people stood up and made the promise too. Josiah helped them clean every bad and false thing out of the land. They got rid of all the idols. They wanted to follow only the true God."]}, {"type": "story", "img": "images/book/jul-21-2.jpg", "alt": "Illustration: Josiah also helped the people celebrate a special holy day to remember God.", "text": ["Josiah also helped the people celebrate a special holy day to remember God. There had not been a celebration like it for a very long time. Everyone’s heart turned back to Heavenly Father.", "When we make promises to God, we call them covenants. Keeping our promises to Heavenly Father makes us strong and happy. Josiah led the people back to God. We can keep our promises too."]}, {"type": "moment", "img": "images/book/jul-21-3.jpg", "alt": "Illustration: Put your hand over your heart and make a promise: “I will follow Heavenly Father.” That’s a covenant — a speci…", "text": ["Put your hand over your heart and make a promise: “I will follow Heavenly Father.” That’s a covenant — a special promise to God! Josiah and all the people did this together. Promises to God make our hearts strong. Let’s keep our promises!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["A promise to Heavenly Father is called a covenant, and keeping it makes you strong! Josiah promised to follow God, and so did all the people. You make promises too — to be kind, to obey, to pray. What good promise can you keep this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-21-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What promise did Josiah and the people make to God? What did they clean out of the land?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-21-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n1', 7, 'Week 4 · Night 1', 'King Asa Calls on God', '2 Chronicles 14', '[{"type": "cover", "img": "images/book/jul-22-0.jpg", "alt": "Cover illustration for “King Asa Calls on God”"}, {"type": "story", "img": "images/book/jul-22-1.jpg", "alt": "Illustration: Asa was a good king of Judah who loved Heavenly Father.", "text": ["Asa was a good king of Judah who loved Heavenly Father. He helped the people get rid of idols and follow God. One day, a HUGE army came to fight against them. There were so many enemies — way more than Asa’s soldiers!", "Asa wasn’t sure how they could win. But he didn’t give up or panic. Instead, he cried out to Heavenly Father. “Lord, only You can help us! We trust in You.”"]}, {"type": "story", "img": "images/book/jul-22-2.jpg", "alt": "Illustration: Heavenly Father heard Asa’s prayer.", "text": ["Heavenly Father heard Asa’s prayer. He helped the small army of Judah win! The big enemy army ran away. God’s power is bigger than any problem.", "It doesn’t matter how big a problem is. With Heavenly Father, anything is possible! Asa didn’t count on numbers — he counted on God. When we call on the Lord, He helps us. He is our greatest helper."]}, {"type": "moment", "img": "images/book/jul-22-3.jpg", "alt": "Illustration: Make yourself small and say “uh oh, the problem is so big!” Now reach up high to Heavenly Father and call, “He…", "text": ["Make yourself small and say “uh oh, the problem is so big!” Now reach up high to Heavenly Father and call, “Help me, Lord!” With God, even big problems become small. He is stronger than anything you face!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["No problem is too big for Heavenly Father! Asa had a tiny army and a giant enemy, but he trusted God and won. When something feels too big for you, call on the Lord. What big thing can you ask Heavenly Father to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-22-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Was Asa’s army big or small? Who helped Asa win against the giant army?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-22-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n2', 7, 'Week 4 · Night 2', 'Be Strong and Don’t Give Up', '2 Chronicles 15', '[{"type": "cover", "img": "images/book/jul-23-0.jpg", "alt": "Cover illustration for “Be Strong and Don’t Give Up”"}, {"type": "story", "img": "images/book/jul-23-1.jpg", "alt": "Illustration: A man named Azariah had a message from Heavenly Father for King Asa.", "text": ["A man named Azariah had a message from Heavenly Father for King Asa. He said, “The Lord is with you when you are with Him. If you look for God, you will find Him!” That was wonderful news.", "Then Azariah said something important: “Be strong! Don’t let your hands be weak. Your good work will be rewarded.” This helped King Asa feel brave and happy."]}, {"type": "story", "img": "images/book/jul-23-2.jpg", "alt": "Illustration: So Asa kept working hard to follow God.", "text": ["So Asa kept working hard to follow God. He kept getting rid of bad things and doing good. The people gathered together and promised to seek the Lord with all their hearts.", "Heavenly Father wants us to be strong and not give up doing good. When we seek Him, we always find Him. Our good work is never wasted. Keep going — God will reward you!"]}, {"type": "moment", "img": "images/book/jul-23-3.jpg", "alt": "Illustration: Flex your arms and make your strongest muscles!", "text": ["Flex your arms and make your strongest muscles! Say loudly, “Be strong! Don’t give up!” That’s the message God gave to King Asa. When you feel like quitting, be strong and keep doing good. God sees all your good work!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Be strong and don’t give up doing good! Sometimes good things are hard, and you might want to quit. But Heavenly Father says, “Be strong — your good work will be rewarded!” What good thing can you keep doing, even when it’s hard?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-23-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Azariah tell King Asa to do? What happens when we look for Heavenly Father?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-23-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n3', 7, 'Week 4 · Night 3', 'When Asa Forgot to Trust', '2 Chronicles 16', '[{"type": "cover", "img": "images/book/jul-24-0.jpg", "alt": "Cover illustration for “When Asa Forgot to Trust”"}, {"type": "story", "img": "images/book/jul-24-1.jpg", "alt": "Illustration: King Asa had trusted God for many years.", "text": ["King Asa had trusted God for many years. But when a new problem came, Asa forgot to ask Heavenly Father first. Instead, he tried to fix it all by himself. He made a deal with another king for help.", "A wise messenger named Hanani came to Asa. He said, “Asa, why didn’t you trust the Lord this time? God’s eyes look all over the earth to help those who trust Him.”"]}, {"type": "story", "img": "images/book/jul-24-2.jpg", "alt": "Illustration: Asa felt upset because he knew he had made a mistake.", "text": ["Asa felt upset because he knew he had made a mistake. Even good King Asa forgot to lean on God this time. We all make mistakes sometimes. The important thing is to remember to trust God again.", "Heavenly Father wants us to trust Him in EVERYTHING — big and small. Even when we forget, we can turn back to Him. God is always watching, ready to help. Let’s remember to ask Him first."]}, {"type": "moment", "img": "images/book/jul-24-3.jpg", "alt": "Illustration: Point to your eyes, then point all around the room — Heavenly Father’s eyes see everywhere, looking for people…", "text": ["Point to your eyes, then point all around the room — Heavenly Father’s eyes see everywhere, looking for people to help! Now point up and say, “I’ll trust You first, Heavenly Father.” Even when we forget, we can always turn back to God."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Remember to trust Heavenly Father in everything — even the little things! Asa was a good king, but one time he forgot to ask God first. We all forget sometimes, and that’s okay. We can always turn back and trust Him again. What can you remember to ask Heavenly Father about?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-24-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Asa forget to do when a new problem came? Who is always watching, ready to help us?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-24-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n4', 7, 'Week 4 · Night 4', 'Judges Who Are Fair', '2 Chronicles 19', '[{"type": "cover", "img": "images/book/jul-25-0.jpg", "alt": "Cover illustration for “Judges Who Are Fair”"}, {"type": "story", "img": "images/book/jul-25-1.jpg", "alt": "Illustration: King Jehoshaphat loved Heavenly Father.", "text": ["King Jehoshaphat loved Heavenly Father. He wanted everyone in the land to be treated fairly. So he chose good, wise people to be judges. Judges help decide what is right and fair.", "Jehoshaphat told the judges something important. “Be careful and fair. Remember, you are not just judging for people — you are judging for the Lord!” He wanted them to be honest and kind."]}, {"type": "story", "img": "images/book/jul-25-2.jpg", "alt": "Illustration: He told them, “Do your work with a happy, brave heart, and God will be with the good.” The judges promised to…", "text": ["He told them, “Do your work with a happy, brave heart, and God will be with the good.” The judges promised to be fair to everyone. They wanted to please Heavenly Father.", "Heavenly Father wants us to be fair and kind to everyone. We treat all people the way God would want. Being fair makes families and friends happy. Fairness shows we love God and His children."]}, {"type": "moment", "img": "images/book/jul-25-3.jpg", "alt": "Illustration: Hold out both hands flat like a balance scale and keep them even and level.", "text": ["Hold out both hands flat like a balance scale and keep them even and level. That’s being fair — treating everyone the same! Jehoshaphat wanted everyone to be treated fairly. Can you keep your hands nice and even, like fairness?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father wants you to be fair and kind to everyone! That means taking turns, sharing, and not leaving anyone out. King Jehoshaphat wanted everyone treated fairly. How can you be fair and kind to someone today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-25-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did King Jehoshaphat want the judges to be? Who did he say they were really judging for?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-25-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n5', 7, 'Week 4 · Night 5', 'Our Eyes Are upon Thee', '2 Chronicles 20', '[{"type": "cover", "img": "images/book/jul-26-0.jpg", "alt": "Cover illustration for “Our Eyes Are upon Thee”"}, {"type": "story", "img": "images/book/jul-26-1.jpg", "alt": "Illustration: A huge army was coming to fight King Jehoshaphat’s people.", "text": ["A huge army was coming to fight King Jehoshaphat’s people. There were so many enemies! Jehoshaphat felt afraid. But he knew exactly what to do — he gathered everyone to pray.", "Jehoshaphat prayed a beautiful prayer: “Heavenly Father, we don’t know what to do. But OUR EYES ARE UPON THEE.” That means, “We are looking to You for help, Lord!”"]}, {"type": "story", "img": "images/book/jul-26-2.jpg", "alt": "Illustration: Heavenly Father answered, “Don’t be afraid.", "text": ["Heavenly Father answered, “Don’t be afraid. This battle is Mine. Just stand still and watch Me save you.” So the next day, the people SANG praises to God as they marched out. And the enemies were defeated without Judah even fighting!", "When we don’t know what to do, we can look to Heavenly Father. “Our eyes are upon Thee” means we trust God to lead us. He fights our battles. We just need to keep our eyes on Him."]}, {"type": "moment", "img": "images/book/jul-26-3.jpg", "alt": "Illustration: Point to your eyes, then look up toward heaven and say, “Our eyes are upon Thee!” That means, “I’m looking to…", "text": ["Point to your eyes, then look up toward heaven and say, “Our eyes are upon Thee!” That means, “I’m looking to You, Heavenly Father!” When you don’t know what to do, look up to God. He always knows the way."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you don’t know what to do, look to Heavenly Father — “our eyes are upon Thee!” Jehoshaphat didn’t know how to win, so he kept his eyes on God. And God saved them! When have you not known what to do? You can look to Him!"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-26-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Jehoshaphat pray when he was scared? What did the people do instead of fighting?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-26-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n6', 7, 'Week 4 · Night 6', 'The King Who Forgot to Stay Humble', '2 Chronicles 26', '[{"type": "cover", "img": "images/book/jul-27-0.jpg", "alt": "Cover illustration for “The King Who Forgot to Stay Humble”"}, {"type": "story", "img": "images/book/jul-27-1.jpg", "alt": "Illustration: Uzziah became king when he was just sixteen.", "text": ["Uzziah became king when he was just sixteen. He loved God, and as long as he sought the Lord, God helped him do amazing things. He built towers and won battles. He became very strong and famous.", "But when Uzziah got strong, he started to feel proud. He forgot that his blessings came from Heavenly Father. He thought he could do whatever he wanted, even break God’s rules."]}, {"type": "story", "img": "images/book/jul-27-2.jpg", "alt": "Illustration: Uzziah went into the temple to do something only the priests were supposed to do.", "text": ["Uzziah went into the temple to do something only the priests were supposed to do. The priests said, “Please don’t — that’s not your job!” But Uzziah got angry instead of humble. Then he got sick right away.", "Pride means thinking we’re better than others and forgetting God. Heavenly Father wants us to stay humble and grateful. When we remember our blessings come from Him, we stay happy and close to God. Humble hearts please the Lord."]}, {"type": "moment", "img": "images/book/jul-27-3.jpg", "alt": "Illustration: Puff up your chest big and proud, then let all the air out and bow your head humbly.", "text": ["Puff up your chest big and proud, then let all the air out and bow your head humbly. Ahh, that feels better! Heavenly Father loves a humble heart. Let’s stay thankful and remember our blessings come from Him."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Stay humble and remember that your blessings come from Heavenly Father! King Uzziah did great things, but then he got proud and forgot God. Being humble means saying “thank you” to God and following His rules. What can you thank Heavenly Father for tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-27-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What happened to Uzziah’s heart when he became strong? Does Heavenly Father want us proud or humble?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-27-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n7', 7, 'Week 4 · Night 7', 'Come Celebrate with God', '2 Chronicles 30', '[{"type": "cover", "img": "images/book/jul-28-0.jpg", "alt": "Cover illustration for “Come Celebrate with God”"}, {"type": "story", "img": "images/book/jul-28-1.jpg", "alt": "Illustration: Good King Hezekiah wanted everyone to come back to Heavenly Father.", "text": ["Good King Hezekiah wanted everyone to come back to Heavenly Father. He sent invitations all across the land. “Come to God’s house! Let’s celebrate and remember the Lord together!”", "Some people laughed and didn’t want to come. That made Hezekiah a little sad. But many other people humbled their hearts and said, “Yes! We will come!” They traveled to join the celebration."]}, {"type": "story", "img": "images/book/jul-28-2.jpg", "alt": "Illustration: Everyone gathered together to worship and remember Heavenly Father.", "text": ["Everyone gathered together to worship and remember Heavenly Father. There was so much joy and singing and gladness! It was the happiest celebration in a very long time. The people’s hearts turned back to God.", "Heavenly Father always invites us to come back to Him. There is great joy in worshiping God together. When we come to Him with a humble heart, He welcomes us with love. Coming back to God always brings happiness."]}, {"type": "moment", "img": "images/book/jul-28-3.jpg", "alt": "Illustration: Wave your arm like you’re inviting friends over: “Come, come celebrate with God!” Now clap and cheer for the h…", "text": ["Wave your arm like you’re inviting friends over: “Come, come celebrate with God!” Now clap and cheer for the happy celebration! Heavenly Father loves it when we come to Him. There is so much joy in worshiping together. Can you feel the happiness?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father always invites you to come close to Him — and it brings great joy! King Hezekiah invited everyone to celebrate God, and those who came were so happy. You can come to Heavenly Father anytime, through prayer, church, and good choices. How can you come closer to Heavenly Father this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-28-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did King Hezekiah invite everyone to do? How did the people feel when they came to celebrate God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-28-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

-- ---------------------------------------------------------------------
-- WHICH STORIES ARE FREE
-- The same three as meta.freeStoryIds in data/virtue-library.js. Keep the
-- two lists the same, or a story is free in one place and not the other.
-- ---------------------------------------------------------------------
update public.book_nights set is_free = (id in ('b6-w3-n1', 'b7-w1-n7', 'b6-w3-n4'));

-- ---------------------------------------------------------------------
-- DID IT WORK? Last statement, so this is what the Results panel shows.
-- ---------------------------------------------------------------------
select book, count(*) as nights,
       count(*) filter (where is_free) as "free ones"
  from public.book_nights group by book order by book;
